Lemma ppl_noargs_shift : forall fuel s cnt ps r,
  printf_pieces_loop fuel s [] 0 = Some (ps, r) -> 0 <= cnt -> cnt + r <= INT_MAX ->
  printf_pieces_loop fuel s [] cnt = Some (ps, cnt + r).
Proof.
