Lemma lit_run_app : forall lit rest,
  Forall (fun c => c <> 0 /\ c <> 37) lit ->
  match rest with [] => True | c1 :: _ => c1 = 0 \/ c1 = 37 end ->
  lit_run (lit ++ rest) = lit.
Proof.
